import React from "react";
import {observer} from 'mobx-react';

import {execWhen} from 'utils/Utils';
import {renderLeftButtonsForExpiryOnly_firebase} from 'utils/ComponentUtils';
import {TabledTopPanel} from 'components/tables';
import Popover from 'components/popovers/Popover';

import ATab from './ATab';
import BigCalendarWrapper from './BigCalendarWrapper';
import DataSource from './data';

import ProfileSharedDialog from "../../common/documents/ProfileSharedDialog";

import style from "./TabExpiredSharedDocs.lazy.css";

@observer
class Main extends ATab {

    constructor(props) {
        super(props, style);
        this.classNames += " LeftButtonsForExpiryOnlyPage";
    }
    
    onSelectEvent(event) {
        const {profileDialog} = this.refs;
        const {key, displayTitle, item} = event;
        console.log(event)
        switch (key) {
            case '01_Project_Plan':
                profileDialog.extraProp('path', 'plugin_sheq_assist/01_Project_Plan/').open(item, displayTitle);
                break;
            case 'CompanyDocument':
                profileDialog.extraProp('path', 'plugin_sheq_assist/01_Project_Plan/documents/').open(item, displayTitle);
                break;
            case '02_IMS_Policies':
                profileDialog.extraProp('path', 'plugin_sheq_assist/02_IMS_Policies/').open(item, displayTitle);
                break;
            case '05_Training_ToolboxTalks':
                profileDialog.extraProp('path', 'plugin_sheq_assist/05_Trainings/toolbox-talks/').open(item, displayTitle);
                break;
            case '08_Environmental_Aspects_Checklist':
                profileDialog.extraProp('path', 'plugin_sheq_assist/08_Environmental_Aspects/checklist/').open(item, displayTitle);
                break;
            case '08_Environmental_Aspects_QAP':
                profileDialog.extraProp('path', 'plugin_sheq_assist/08_Environmental_Aspects/qap/').open(item, displayTitle);
                break;
            case '08_Environmental_Aspects_EMP':
                profileDialog.extraProp('path', 'plugin_sheq_assist/08_Environmental_Aspects/emp/').open(item, displayTitle);
                break;
            case '16_Emergency_Preparedness_Emergency_Procedure':
                profileDialog.extraProp('path', 'plugin_sheq_assist/16_Emergency_Preparedness/emergency-procedure/').open(item, displayTitle);
                break;
            case 'COVID_Management_Document':
                profileDialog.extraProp('path', 'plugin_sheq_assist/COVID_Management/documents/').open(item, displayTitle);
                break;
        }
    }

    onLoadList() {
        execWhen(() => !!this.refs.bigCalendarWrapper).then(() => {
            const {bigCalendarWrapper: {selectedDate, selectedView}} = this.refs;
            console.log(selectedDate, selectedView)
            DataSource.documents_shared.load(this.state, selectedDate, selectedView);
        });
    }
    
    update() {
        this.onLoadList();
    }

    render() {
        return (<div id="TabExpiredSharedDocs-page" className={this.classNames + " TabExpiredSharedDocs-page calendar-page"}>
            <div className="page-title">
                <h3>Calendar</h3>
                <TabledTopPanel ref="tabledTopPanel" titleSinglar="Event" titlePlural="events">
                    {renderLeftButtonsForExpiryOnly_firebase.call(this)}
                </TabledTopPanel>	
                <div className="clearfix"/>
            </div>
            <BigCalendarWrapper 
                ref="bigCalendarWrapper"
                state={this.state} 
                onSelectEvent={this.onSelectEvent}
                onYearDateClick={this.onYearDateClick} 
                onYearMonthClick={this.onYearMonthClick}/>
        
            <ProfileSharedDialog ref="profileDialog"/>  
            <Popover key="popover" ref="popover"/>
        </div>);
    }
}

export default Main;